        + @"|\bquien\b.*\b(mejor|peor|mas (alto|alta|bajo|baja)s?)\b",
        RegexOptions.CultureInvariant, matchTimeoutMilliseconds: TiempoLimiteRegex.Milisegundos)]
    private static partial Regex PatronesAgregados();
}
