using TutorFlow.Core.Asistente;

namespace TutorFlow.Core.Tests.Asistente;

public sealed class SinSemillaTests
{
    [Theory]
    [InlineData(typeof(SolicitudLlm))]
    [InlineData(typeof(AjustesDelModelo))]
    [Trait("CA", "CA-07")]
    [Trait("ESC", "ESC-192")]
    [Trait("D", "D-85")]
    public void ESC_192_h_Ningun_tipo_de_la_solicitud_al_modelo_lleva_semilla(Type tipo)
    {
        Assert.DoesNotContain(tipo.GetProperties(), p => p.Name.Contains("Semilla", StringComparison.OrdinalIgnoreCase) || p.Name.Contains("Seed", StringComparison.OrdinalIgnoreCase));
    }

    [Fact]
    [Trait("CA", "CA-07")]
    [Trait("ESC", "ESC-192")]
    [Trait("D", "D-85")]
    public async Task ESC_192_h_La_solicitud_que_recibe_el_modelo_no_expone_semilla_en_ninguna_llamada_del_reintento()
    {
        var escenario = EscenarioAsistente.Con(EscenarioAsistente.Fijo("Tu promedio es 1.23."));

        await escenario.PreguntarAsync(new TutorFlow.Core.Autorizacion.Usuario(TutorFlow.Core.Autorizacion.Rol.Estudiante, "EST-001"), EscenarioAsistente.PreguntaPromedio);

        Assert.True(escenario.Llm.Solicitudes.Count >= 2);
        Assert.All(escenario.Llm.Solicitudes, s => Assert.DoesNotContain(s.GetType().GetProperties(), p => p.Name.Contains("Semilla", StringComparison.OrdinalIgnoreCase)));
    }
}

